const cfg = $('Config').first().json.cfg;
const helpers = this.helpers;
const SB = cfg.supabase_url.replace(/\/+$/, '') + '/rest/v1';

// New Supabase keys (sb_publishable_/sb_secret_) are NOT JWTs: send them only in the "apikey" header.
// Legacy keys (eyJ... JWTs) are sent in both headers.
const authHeaders = () => {
  const h = { apikey: cfg.supabase_key };
  if (!String(cfg.supabase_key).startsWith('sb_')) h.Authorization = 'Bearer ' + cfg.supabase_key;
  return h;
};
// ---------- MULTI-TENANT: every query of a logged-in rep is pinned to HIS company ----------
// The bot talks to Supabase with the secret key (it bypasses RLS), so the isolation is forced here, in ONE place:
//  - GET / PATCH / DELETE on a company table get  &tenant_id=eq.<his company>
//  - POST gets tenant_id injected
// (the database also refuses any cross-company reference, so a bug here can not leak data either)
const TENANT_TABLES = new Set(['clients', 'products', 'visits', 'visit_items', 'payments', 'collections', 'stock_issues', 'stock_issue_items', 'product_costs', 'product_requests', 'rep_sessions']);
function currentTenant() { try { const r = $('Init').first().json.rep; return (r && r.tenant_id) || null; } catch (e) { return null; } }
async function sb(method, path, body, prefer) {
  const tid = currentTenant();
  const table = String(path).split('?')[0].replace(/^\//, '');
  if (tid && TENANT_TABLES.has(table)) {
    if (method === 'GET' || method === 'PATCH' || method === 'DELETE') path += (path.indexOf('?') >= 0 ? '&' : '?') + 'tenant_id=eq.' + tid;
    else if (method === 'POST' && body && typeof body === 'object') body = Array.isArray(body) ? body.map(o => Object.assign({ tenant_id: tid }, o)) : Object.assign({ tenant_id: tid }, body);
  }
  const headers = Object.assign({ 'Content-Type': 'application/json' }, authHeaders());
  if (prefer) headers.Prefer = prefer;
  const opt = { method, url: SB + path, headers, json: true };
  if (body !== undefined) opt.body = body;
  return await helpers.httpRequest(opt);
}
async function tg(method, payload) {
  return await helpers.httpRequest({ method: 'POST', url: 'https://api.telegram.org/bot' + cfg.bot_token + '/' + method, body: payload, json: true });
}
const send = (chat_id, text, extra) => tg('sendMessage', Object.assign({ chat_id, text }, extra || {}));
const unitAr = u => ({ carton: 'كرتونة', box: 'علبة', pack: 'باكو', piece: 'قطعة' }[u] || u || '');
const fmt = n => Number(n || 0).toLocaleString('en-US', { maximumFractionDigits: 2 });
const STOCK_BTN = '📦 استلام بضاعة';
const LOC_KB = { keyboard: [[{ text: '📍 أرسل موقعي', request_location: true }], [{ text: STOCK_BTN }]], resize_keyboard: true, is_persistent: true };
const setSession = (rep_id, fields) => sb('POST', '/rep_sessions?on_conflict=rep_id', Object.assign({ rep_id }, fields), 'resolution=merge-duplicates');

function nowInfo() {
  const d = new Date();
  const tz = cfg.timezone || 'Africa/Cairo';
  const parts = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23' }).formatToParts(d);
  const g = t => parts.find(p => p.type === t).value;
  const offRaw = new Intl.DateTimeFormat('en-US', { timeZone: tz, timeZoneName: 'longOffset' }).formatToParts(d).find(p => p.type === 'timeZoneName').value.replace('GMT', '');
  const off = offRaw || '+00:00';
  const day = new Intl.DateTimeFormat('ar-EG', { timeZone: tz, weekday: 'long' }).format(d);
  return { iso: g('year') + '-' + g('month') + '-' + g('day') + 'T' + g('hour') + ':' + g('minute') + ':' + g('second') + off, day };
}
function arDay(iso) {
  try { return new Intl.DateTimeFormat('ar-EG', { timeZone: cfg.timezone || 'Africa/Cairo', weekday: 'long' }).format(new Date(iso)); } catch (e) { return ''; }
}
const validIso = s => (typeof s === 'string' && s && !isNaN(Date.parse(s))) ? s : null;

const normAr = s => (s || '').toString().toLowerCase()
  .replace(/[\u064B-\u065F\u0670\u0640]/g, '')
  .replace(/[إأآ]/g, 'ا').replace(/ى/g, 'ي').replace(/ة/g, 'ه')
  .replace(/[^\p{L}\p{N}\s]/gu, ' ').replace(/\s+/g, ' ').trim();
const toks = s => normAr(s).split(' ').filter(Boolean).map(w => w.replace(/^ال/, '')).filter(Boolean);
function nameScore(a, b) {
  const ta = toks(a), tb = toks(b);
  if (!ta.length || !tb.length) return 0;
  const inter = ta.filter(t => tb.includes(t)).length;
  return 0.5 * inter / Math.max(ta.length, tb.length) + 0.5 * inter / Math.min(ta.length, tb.length);
}
function clientCandidates(name, clients) {
  if (!name) return [];
  return clients
    .map(c => ({ id: c.id, name: c.name, score: Math.max(nameScore(name, c.name), ...(c.aliases || []).map(a => nameScore(name, a))) }))
    .filter(c => c.score >= 0.5).sort((x, y) => y.score - x.score).slice(0, 3);
}
const itemsTotal = d => (d.items || []).reduce((s, i) => s + (Number(i.quantity) || 0) * (Number(i.unit_price) || 0), 0);

function renderSummary(d, header) {
  const L = [];
  if (header) L.push(header);
  const cm = d.client_match;
  let who = d.client_name || '⚠️ العميل غير محدد';
  if (d.client_name) {
    if (cm === 'new' || cm === 'none') who += ' (عميل جديد)';
    else if (cm === 'low') who += ' ⚠️ اختار العميل من الأزرار';
  }
  L.push('👤 ' + who);
  if (d.client_name && !d.client_id && (cm === 'new' || cm === 'none')) L.push('📍 هنأكد معاك موقع العميل قبل التسجيل');
  L.push({ sale: '🛒 بيع', follow_up: '🤝 متابعة', collection: '💵 تحصيل' }[d.visit_type] || '🛒 بيع');
  const items = d.items || [];
  let total = 0;
  for (const it of items) {
    const lt = it.unit_price != null ? it.quantity * it.unit_price : null;
    if (lt) total += lt;
    L.push('• ' + it.quantity + ' ' + unitAr(it.unit) + ' ' + it.product_text + (it.factor && it.factor !== 1 ? ' (= ' + fmt(it.base_qty) + ' ' + unitAr(it.base_unit) + ')' : '') + (it.unit_price != null ? ' × ' + fmt(it.unit_price) + ' = ' + fmt(lt) : ' ⚠️ السعر غير محدد'));
  }
  if (items.length) L.push('الإجمالي: ' + fmt(total));
  const p = d.payment || {};
  if (p.amount_paid > 0) {
    const mth = { cash: 'كاش', transfer: 'تحويل', cheque: 'شيك' }[p.method];
    L.push('💰 المدفوع: ' + fmt(p.amount_paid) + (total > 0 ? ' / المتبقي: ' + fmt(Math.max(total - p.amount_paid, 0)) : '') + (mth ? ' (' + mth + ')' : ''));
  } else if (p.status === 'credit') L.push('💰 آجل (لم يُدفع شيء)');
  if (d.collection && d.collection.due_at) L.push('🗓 تحصيل: ' + arDay(d.collection.due_at) + ' ' + d.collection.due_at.slice(0, 10) + (d.collection.amount_due ? ' — ' + fmt(d.collection.amount_due) : ''));
  if (d.next_visit_at) L.push('🔁 الزيارة الجاية: ' + arDay(d.next_visit_at) + ' ' + d.next_visit_at.slice(0, 10));
  if (d.client_notes) L.push('📝 ' + d.client_notes);
  for (const q of d.questions || []) L.push('❓ ' + q);
  return L.join('\n');
}
function kb(visitId, d) {
  const rows = [];
  if (d.client_match === 'low' && (d._candidates || []).length) {
    d._candidates.forEach((c, i) => rows.push([{ text: '👤 ' + c.name, callback_data: 'pick:' + visitId + ':' + i }]));
    rows.push([{ text: '➕ عميل جديد', callback_data: 'pick:' + visitId + ':new' }]);
  }
  rows.push([{ text: '✅ تأكيد', callback_data: 'confirm:' + visitId }, { text: '✏️ تعديل', callback_data: 'edit:' + visitId }]);
  rows.push([{ text: '🗑 إلغاء', callback_data: 'cancel:' + visitId }]);
  return { inline_keyboard: rows };
}

// ---------- Gemini chat with model fallback (OpenAI-compatible endpoint) ----------
const GEM_CHAT = 'https://generativelanguage.googleapis.com/v1beta/openai/chat/completions';
const gemCall = (model, messages, useJson) => {
  const body = { model, messages };
  if (useJson) body.response_format = { type: 'json_object' };
  return helpers.httpRequest({ method: 'POST', url: GEM_CHAT, json: true, timeout: 120000,
    headers: { Authorization: 'Bearer ' + cfg.gemini_key, 'Content-Type': 'application/json' }, body });
};
const gemText = r => {
  const c = r && r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content;
  if (Array.isArray(c)) return c.map(p => p.text || '').join('');
  return c || '';
};
async function llmChat(models, messages, wantJson) {
  let lastErr = null;
  for (const model of models) {
    for (const useJson of (wantJson ? [true, false] : [false])) {
      try {
        const content = gemText(await gemCall(model, messages, useJson));
        if (!content.trim()) throw new Error('empty response from ' + model);
        return { content, model };
      } catch (e) { lastErr = e; }
    }
  }
  throw lastErr || new Error('no model available');
}
function parseJson(s) {
  try { return JSON.parse(s); } catch (e) {
    const m = (s || '').match(/\{[\s\S]*\}/);
    if (m) { try { return JSON.parse(m[0]); } catch (e2) { /* fallthrough */ } }
    return null;
  }
}

// ---------- Stock (factory invoices) ----------
const lineTotalOf = i => (i.quantity > 0 && i.unit_price != null) ? Math.round(i.quantity * i.unit_price * 100) / 100 : (i.line_total != null ? i.line_total : null);
const stockTotal = d => (d.items || []).reduce((s, i) => s + (lineTotalOf(i) || 0), 0);

function renderStockSummary(d, header) {
  const L = [];
  if (header) L.push(header);
  L.push(d.kind === 'return' ? '↩️ مرتجع للمصنع' : '📦 استلام بضاعة من المصنع');
  const meta = [d.invoice_no ? 'رقم ' + d.invoice_no : null, d.invoice_date || null].filter(Boolean).join(' — ');
  if (meta) L.push('🧾 ' + meta);
  const items = d.items || [];
  for (const it of items) {
    const lt = lineTotalOf(it);
    L.push('• ' + it.quantity + ' ' + unitAr(it.unit) + ' ' + it.product_text + (it.factor && it.factor !== 1 ? ' (= ' + fmt(it.base_qty) + ' ' + unitAr(it.base_unit) + ')' : '') + (it.unit_price != null ? ' × ' + fmt(it.unit_price) : '') + (lt != null ? ' = ' + fmt(lt) : ' ⚠️ السعر غير واضح'));
  }
  const total = stockTotal(d);
  if (items.length) {
    let line = 'الإجمالي المحسوب: ' + fmt(total);
    if (d.declared_total != null) line += ' | على الفاتورة: ' + fmt(d.declared_total) + (Math.abs(d.declared_total - total) > Math.max(1, d.declared_total * 0.01) ? ' ⚠️' : ' ✓');
    L.push(line);
  }
  if (d.legibility === 'poor') L.push('⚠️ الصورة مش واضحة، راجع الأرقام بعناية');
  if (d.digits_style === 'arabic_indic' || d.digits_style === 'mixed') L.push('🔢 الفاتورة فيها أرقام عربية (٠١٢): راجع الأصفار كويس (٤٥٠ مش ٤٥)');
  if (d.notes) L.push('📝 ' + d.notes);
  for (const q of d.questions || []) L.push('❓ ' + q);
  return L.join('\n');
}
function kbStock(id, d) {
  return { inline_keyboard: [
    [{ text: d.duplicate ? '⚠️ تأكيد (متكررة)' : '✅ تأكيد', callback_data: 'sconfirm:' + id }, { text: '✏️ تعديل', callback_data: 'sedit:' + id }],
    [{ text: d.kind === 'return' ? '🔁 حوّلها لاستلام' : '🔁 حوّلها لمرتجع', callback_data: 'skind:' + id }],
    [{ text: '🗑 إلغاء', callback_data: 'scancel:' + id }]
  ] };
}
async function custodyText(rep_id) {
  const rows = await sb('GET', '/rep_stock?rep_id=eq.' + rep_id + '&on_hand=neq.0&select=item,unit,on_hand,on_hand_value&order=item&limit=40');
  if (!rows.length) return '📦 مفيش بضاعة مع حضرتك دلوقتي.';
  let tot = 0;
  const L = ['📦 معاك دلوقتي (كل الفواتير المؤكدة − اللي بعته):'];
  for (const r of rows) { tot += Number(r.on_hand_value || 0); L.push('• ' + fmt(r.on_hand) + ' ' + unitAr(r.unit) + ' ' + r.item + (Number(r.on_hand) < 0 ? ' ⚠️ (سالب)' : '')); }
  L.push('💼 قيمة العهدة: ' + fmt(tot));
  return L.join('\n');
}

// several vision models, to cross-check an invoice reading (returns [{model, content}], at most `max`)
async function llmChatMulti(models, messages, max) {
  const outs = []; let lastErr = null;
  for (const model of models) {
    if (outs.length >= max) break;
    try {
      const content = gemText(await gemCall(model, messages, false));
      if (!content.trim()) throw new Error('empty response from ' + model);
      outs.push({ model, content });
    } catch (e) { lastErr = e; }
  }
  if (!outs.length) throw lastErr || new Error('no vision model available');
  return outs;
}

// ---------- product catalog: the reference the bot checks every message against ----------
const UNIT_SYN = {
  carton: ['carton', 'كرتونة', 'كرتونه', 'كرتون', 'كارتونة', 'كراتين', 'كرتونات'],
  box: ['box', 'علبة', 'علبه', 'علب'],
  pack: ['pack', 'packet', 'باكو', 'باكت', 'باكوهات', 'عبوة', 'عبوه'],
  piece: ['piece', 'قطعة', 'قطعه', 'قطع', 'حبة', 'حبه'],
  dozen: ['dozen', 'دستة', 'دسته', 'دست'],
  bag: ['bag', 'كيس', 'اكياس', 'أكياس', 'شوال', 'شوالات'],
  bottle: ['bottle', 'زجاجة', 'زجاجه', 'ازازة', 'إزازة', 'قزازة'],
  kg: ['kg', 'كيلو', 'كجم']
};
const unitKey = u => {
  const n = normAr(u); if (!n) return '';
  for (const k of Object.keys(UNIT_SYN)) if (UNIT_SYN[k].some(a => normAr(a) === n)) return k;
  return n;
};
const sameUnit = (a, b) => !!a && !!b && unitKey(a) === unitKey(b);
const unitsOf = p => [p.unit].concat((p.alt_units || []).map(a => a.name)).filter(Boolean);
function unitFactor(p, unitText) {
  if (!unitText || sameUnit(unitText, p.unit)) return { factor: 1, known: true };
  for (const a of (p.alt_units || [])) if (sameUnit(unitText, a.name)) return { factor: Number(a.factor) > 0 ? Number(a.factor) : 1, known: true };
  return { factor: 1, known: false };
}
// code-side matching (does not depend on the AI): exact name/alias, or one clearly best fuzzy match
function matchProduct(text, products) {
  const n = normAr(text); if (!n) return null;
  const scored = products.map(p => ({ p, score: Math.max(...[p.name].concat(p.aliases || []).map(x => normAr(x) === n ? 1 : nameScore(text, x))) })).sort((a, b) => b.score - a.score);
  if (!scored.length || scored[0].score < 0.9) return null;
  if (scored[1] && scored[1].score >= 0.9 && scored[1].score >= scored[0].score - 0.05) return null;   // ambiguous
  return scored[0].p;
}
// normalizes items against the catalog (product, unit factor, base quantity) and returns warnings for the rep
function catalogCheck(items, products, mode) {
  const q = [];
  const byId = new Map(products.map(p => [p.id, p]));
  const tol = (Number(cfg.price_tolerance_pct) || 20) / 100;
  for (const it of items) {
    let p = it.product_id ? byId.get(it.product_id) : null;
    if (!p) p = matchProduct(it.product_text, products);
    it.factor = 1; it.base_qty = it.quantity; it.base_unit = it.unit || null;
    if (!p) {
      it.product_id = null;
      q.push('«' + it.product_text + '» مش في قايمة الأصناف (مش هيتخصم من العهدة ومفيش مرجع سعر).');
      continue;
    }
    it.product_id = p.id; it.product_text = p.name;
    if (!it.unit) it.unit = p.unit;
    const u = unitFactor(p, it.unit);
    if (!u.known) q.push('الوحدة «' + unitAr(it.unit) + '» مش معرّفة للصنف «' + p.name + '» (المعرّف: ' + unitsOf(p).map(unitAr).join('، ') + ').');
    it.factor = u.factor; it.base_qty = Math.round(it.quantity * u.factor * 100) / 100; it.base_unit = p.unit;
    if (it.unit_price != null && it.unit_price > 0) {
      const basePrice = it.unit_price / u.factor;
      const ref = mode === 'receipt' ? p.cost_price : p.default_price;
      const refName = mode === 'receipt' ? 'سعر المصنع' : 'سعر القايمة';
      const per = ' للـ' + unitAr(p.unit);
      if (mode === 'sale' && p.min_price != null && basePrice < Number(p.min_price) - 1e-9) {
        q.push('⚠️ سعر «' + p.name + '» (' + fmt(basePrice) + per + ') أقل من أقل سعر مسموح (' + fmt(p.min_price) + ').');
      } else if (ref != null && Number(ref) > 0) {
        const r = basePrice / Number(ref);
        if (r <= 0.2 || r >= 5) q.push('⚠️ سعر «' + p.name + '» (' + fmt(basePrice) + per + ') مختلف جدًا عن ' + refName + ' (' + fmt(ref) + ')، ممكن صفر غلط.');
        else if (Math.abs(r - 1) > tol) q.push('سعر «' + p.name + '» (' + fmt(basePrice) + per + ') غير ' + refName + ' (' + fmt(ref) + ').');
      }
    }
  }
  return q;
}
async function noteUnknownProducts(items, rep_id) {
  const names = Array.from(new Set((items || []).filter(i => !i.product_id && i.product_text).map(i => String(i.product_text).trim()).filter(Boolean)));
  for (const name of names) {
    try { await sb('POST', '/product_requests?on_conflict=tenant_id,name', { name, rep_id, last_seen: new Date().toISOString() }, 'resolution=merge-duplicates'); } catch (e) { /* table may not exist yet */ }
  }
}
const productsForPrompt = products => products.map(p => ({ id: p.id, name: p.name, aliases: p.aliases, units: unitsOf(p) }));

async function main() {
const first = $input.first().json;
if (first.timestamp && !first.message && !first.callback_query) return [{ json: { route: 'cron' } }];
const upd = Object.assign({}, $input.first().json);
delete upd.cfg;
const m = upd.message, cq = upd.callback_query;
const out = { route: 'ignore', rep: null, chat_id: null, from_id: null, message_id: null, text: null, voice: null, photo: null, caption: null, location: null, cb: null };

if (cq) {
  out.chat_id = cq.message && cq.message.chat && cq.message.chat.id;
  out.from_id = cq.from && cq.from.id;
  out.cb = { id: cq.id, data: cq.data || '', message_id: cq.message && cq.message.message_id };
  out.route = 'callback';
} else if (m && m.chat && m.chat.type === 'private' && m.from) {
  out.chat_id = m.chat.id; out.from_id = m.from.id; out.message_id = m.message_id;
  const media = m.voice || m.audio;
  if (media) { out.voice = { file_id: media.file_id, duration: media.duration || 0 }; out.route = 'voice'; }
  else if (m.photo && m.photo.length) { const p = m.photo[m.photo.length - 1]; out.photo = { file_id: p.file_id, mime: 'image/jpeg' }; out.caption = m.caption || null; out.route = 'photo'; }
  else if (m.document && /^image\//.test(m.document.mime_type || '')) { out.photo = { file_id: m.document.file_id, mime: m.document.mime_type }; out.caption = m.caption || null; out.route = 'photo'; }
  else if (m.document && m.document.mime_type === 'application/pdf') { out.route = 'pdf'; }
  else if (m.location) { out.location = { lat: m.location.latitude, lng: m.location.longitude }; out.route = 'location'; }
  else if (typeof m.text === 'string') {
    out.text = m.text.trim();
    if (out.text.startsWith('/start')) out.route = 'start';
    else if (out.text === STOCK_BTN || out.text.startsWith('/stock')) out.route = 'stock_cmd';
    else if (out.text.startsWith('/cancel')) out.route = 'cancel';
    else if (out.text.startsWith('/')) out.route = 'other';
    else out.route = 'text';
  } else out.route = 'other';
}

if (out.route !== 'ignore' && out.from_id) {
  const reps = await sb('GET', '/reps?telegram_id=eq.' + out.from_id + '&active=eq.true&select=id,name,is_manager,tenant_id,tenants(active,name)');
  out.rep = reps[0] || null;
  if (out.rep && out.rep.tenants && out.rep.tenants.active === false) out.route = 'suspended';   // the company's subscription is stopped
  if (!out.rep) {
    out.route = 'unauthorized';
    const f = (m && m.from) || (cq && cq.from) || {};
    // a company invite link  t.me/<bot>?start=<CODE>  tells us which company the person is joining
    let tenant = null;
    const mm = out.text && out.text.match(/^\/start(?:@\w+)?\s+([A-Za-z0-9_-]{6,40})$/);
    if (mm) { try { tenant = (await sb('GET', '/tenants?invite_code=eq.' + encodeURIComponent(mm[1]) + '&active=eq.true&select=id,name'))[0] || null; } catch (e) { tenant = null; } }
    out.tenant_name = tenant ? tenant.name : null;
    try {   // remember the person so the manager can add him with one tap from the dashboard
      const row = { telegram_id: out.from_id, first_name: f.first_name || null, last_name: f.last_name || null, username: f.username || null, last_seen: new Date().toISOString() };
      if (tenant) row.tenant_id = tenant.id;
      await sb('POST', '/rep_requests?on_conflict=telegram_id', row, 'resolution=merge-duplicates');
    } catch (e) { /* ignore */ }
  }
} else out.route = 'ignore';
return [{ json: out }];

}
try { return await main(); }
catch (e) {
