const cfg = $('Config').first().json.cfg;
const helpers = this.helpers;
const SB = cfg.supabase_url.replace(/\/+$/, '') + '/rest/v1';

// New Supabase keys (sb_publishable_/sb_secret_) are NOT JWTs: send them only in the "apikey" header.
// Legacy keys (eyJ... JWTs) are sent in both headers.
const authHeaders = () => {
  const h = { apikey: cfg.supabase_key };
  if (!String(cfg.supabase_key).startsWith('sb_')) h.Authorization = 'Bearer ' + cfg.supabase_key;
  return h;
};
// ---------- MULTI-TENANT: every query of a logged-in rep is pinned to HIS company ----------
// The bot talks to Supabase with the secret key (it bypasses RLS), so the isolation is forced here, in ONE place:
//  - GET / PATCH / DELETE on a company table get  &tenant_id=eq.<his company>
//  - POST gets tenant_id injected
// (the database also refuses any cross-company reference, so a bug here can not leak data either)
const TENANT_TABLES = new Set(['clients', 'products', 'visits', 'visit_items', 'payments', 'collections', 'stock_issues', 'stock_issue_items', 'product_costs', 'product_requests', 'rep_sessions']);
function currentTenant() { try { const r = $('Init').first().json.rep; return (r && r.tenant_id) || null; } catch (e) { return null; } }
async function sb(method, path, body, prefer) {
  const tid = currentTenant();
  const table = String(path).split('?')[0].replace(/^\//, '');
  if (tid && TENANT_TABLES.has(table)) {
    if (method === 'GET' || method === 'PATCH' || method === 'DELETE') path += (path.indexOf('?') >= 0 ? '&' : '?') + 'tenant_id=eq.' + tid;
    else if (method === 'POST' && body && typeof body === 'object') body = Array.isArray(body) ? body.map(o => Object.assign({ tenant_id: tid }, o)) : Object.assign({ tenant_id: tid }, body);
  }
  const headers = Object.assign({ 'Content-Type': 'application/json' }, authHeaders());
  if (prefer) headers.Prefer = prefer;
  const opt = { method, url: SB + path, headers, json: true };
  if (body !== undefined) opt.body = body;
  return await helpers.httpRequest(opt);
}
async function tg(method, payload) {
  return await helpers.httpRequest({ method: 'POST', url: 'https://api.telegram.org/bot' + cfg.bot_token + '/' + method, body: payload, json: true });
}
const send = (chat_id, text, extra) => tg('sendMessage', Object.assign({ chat_id, text }, extra || {}));
const unitAr = u => ({ carton: 'كرتونة', box: 'علبة', pack: 'باكو', piece: 'قطعة' }[u] || u || '');
const fmt = n => Number(n || 0).toLocaleString('en-US', { maximumFractionDigits: 2 });
const STOCK_BTN = '📦 استلام بضاعة';
const LOC_KB = { keyboard: [[{ text: '📍 أرسل موقعي', request_location: true }], [{ text: STOCK_BTN }]], resize_keyboard: true, is_persistent: true };
const setSession = (rep_id, fields) => sb('POST', '/rep_sessions?on_conflict=rep_id', Object.assign({ rep_id }, fields), 'resolution=merge-duplicates');

function nowInfo() {
  const d = new Date();
  const tz = cfg.timezone || 'Africa/Cairo';
  const parts = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23' }).formatToParts(d);
  const g = t => parts.find(p => p.type === t).value;
  const offRaw = new Intl.DateTimeFormat('en-US', { timeZone: tz, timeZoneName: 'longOffset' }).formatToParts(d).find(p => p.type === 'timeZoneName').value.replace('GMT', '');
  const off = offRaw || '+00:00';
  const day = new Intl.DateTimeFormat('ar-EG', { timeZone: tz, weekday: 'long' }).format(d);
  return { iso: g('year') + '-' + g('month') + '-' + g('day') + 'T' + g('hour') + ':' + g('minute') + ':' + g('second') + off, day };
}
function arDay(iso) {
  try { return new Intl.DateTimeFormat('ar-EG', { timeZone: cfg.timezone || 'Africa/Cairo', weekday: 'long' }).format(new Date(iso)); } catch (e) { return ''; }
}
const validIso = s => (typeof s === 'string' && s && !isNaN(Date.parse(s))) ? s : null;

const normAr = s => (s || '').toString().toLowerCase()
  .replace(/[\u064B-\u065F\u0670\u0640]/g, '')
  .replace(/[إأآ]/g, 'ا').replace(/ى/g, 'ي').replace(/ة/g, 'ه')
  .replace(/[^\p{L}\p{N}\s]/gu, ' ').replace(/\s+/g, ' ').trim();
const toks = s => normAr(s).split(' ').filter(Boolean).map(w => w.replace(/^ال/, '')).filter(Boolean);
function nameScore(a, b) {
  const ta = toks(a), tb = toks(b);
  if (!ta.length || !tb.length) return 0;
  const inter = ta.filter(t => tb.includes(t)).length;
  return 0.5 * inter / Math.max(ta.length, tb.length) + 0.5 * inter / Math.min(ta.length, tb.length);
}
function clientCandidates(name, clients) {
  if (!name) return [];
  return clients
    .map(c => ({ id: c.id, name: c.name, score: Math.max(nameScore(name, c.name), ...(c.aliases || []).map(a => nameScore(name, a))) }))
    .filter(c => c.score >= 0.5).sort((x, y) => y.score - x.score).slice(0, 3);
}
const itemsTotal = d => (d.items || []).reduce((s, i) => s + (Number(i.quantity) || 0) * (Number(i.unit_price) || 0), 0);

function renderSummary(d, header) {
  const L = [];
  if (header) L.push(header);
  const cm = d.client_match;
  let who = d.client_name || '⚠️ العميل غير محدد';
  if (d.client_name) {
    if (cm === 'new' || cm === 'none') who += ' (عميل جديد)';
    else if (cm === 'low') who += ' ⚠️ اختار العميل من الأزرار';
  }
  L.push('👤 ' + who);
  if (d.client_name && !d.client_id && (cm === 'new' || cm === 'none')) L.push('📍 هنأكد معاك موقع العميل قبل التسجيل');
  L.push({ sale: '🛒 بيع', follow_up: '🤝 متابعة', collection: '💵 تحصيل' }[d.visit_type] || '🛒 بيع');
  const items = d.items || [];
  let total = 0;
  for (const it of items) {
    const lt = it.unit_price != null ? it.quantity * it.unit_price : null;
    if (lt) total += lt;
    L.push('• ' + it.quantity + ' ' + unitAr(it.unit) + ' ' + it.product_text + (it.factor && it.factor !== 1 ? ' (= ' + fmt(it.base_qty) + ' ' + unitAr(it.base_unit) + ')' : '') + (it.unit_price != null ? ' × ' + fmt(it.unit_price) + ' = ' + fmt(lt) : ' ⚠️ السعر غير محدد'));
  }
  if (items.length) L.push('الإجمالي: ' + fmt(total));
  const p = d.payment || {};
  if (p.amount_paid > 0) {
    const mth = { cash: 'كاش', transfer: 'تحويل', cheque: 'شيك' }[p.method];
    L.push('💰 المدفوع: ' + fmt(p.amount_paid) + (total > 0 ? ' / المتبقي: ' + fmt(Math.max(total - p.amount_paid, 0)) : '') + (mth ? ' (' + mth + ')' : ''));
  } else if (p.status === 'credit') L.push('💰 آجل (لم يُدفع شيء)');
  if (d.collection && d.collection.due_at) L.push('🗓 تحصيل: ' + arDay(d.collection.due_at) + ' ' + d.collection.due_at.slice(0, 10) + (d.collection.amount_due ? ' — ' + fmt(d.collection.amount_due) : ''));
  if (d.next_visit_at) L.push('🔁 الزيارة الجاية: ' + arDay(d.next_visit_at) + ' ' + d.next_visit_at.slice(0, 10));
  if (d.client_notes) L.push('📝 ' + d.client_notes);
  for (const q of d.questions || []) L.push('❓ ' + q);
  return L.join('\n');
}
function kb(visitId, d) {
  const rows = [];
  if (d.client_match === 'low' && (d._candidates || []).length) {
    d._candidates.forEach((c, i) => rows.push([{ text: '👤 ' + c.name, callback_data: 'pick:' + visitId + ':' + i }]));
    rows.push([{ text: '➕ عميل جديد', callback_data: 'pick:' + visitId + ':new' }]);
  }
  rows.push([{ text: '✅ تأكيد', callback_data: 'confirm:' + visitId }, { text: '✏️ تعديل', callback_data: 'edit:' + visitId }]);
  rows.push([{ text: '🗑 إلغاء', callback_data: 'cancel:' + visitId }]);
  return { inline_keyboard: rows };
}

// ---------- Gemini chat with model fallback (OpenAI-compatible endpoint) ----------
const GEM_CHAT = 'https://generativelanguage.googleapis.com/v1beta/openai/chat/completions';
const gemCall = (model, messages, useJson) => {
  const body = { model, messages };
  if (useJson) body.response_format = { type: 'json_object' };
  return helpers.httpRequest({ method: 'POST', url: GEM_CHAT, json: true, timeout: 120000,
    headers: { Authorization: 'Bearer ' + cfg.gemini_key, 'Content-Type': 'application/json' }, body });
};
const gemText = r => {
  const c = r && r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content;
  if (Array.isArray(c)) return c.map(p => p.text || '').join('');
  return c || '';
};
async function llmChat(models, messages, wantJson) {
  let lastErr = null;
  for (const model of models) {
    for (const useJson of (wantJson ? [true, false] : [false])) {
      try {
        const content = gemText(await gemCall(model, messages, useJson));
        if (!content.trim()) throw new Error('empty response from ' + model);
        return { content, model };
      } catch (e) { lastErr = e; }
    }
  }
  throw lastErr || new Error('no model available');
}
function parseJson(s) {
  try { return JSON.parse(s); } catch (e) {
    const m = (s || '').match(/\{[\s\S]*\}/);
    if (m) { try { return JSON.parse(m[0]); } catch (e2) { /* fallthrough */ } }
    return null;
  }
}

// ---------- Stock (factory invoices) ----------
const lineTotalOf = i => (i.quantity > 0 && i.unit_price != null) ? Math.round(i.quantity * i.unit_price * 100) / 100 : (i.line_total != null ? i.line_total : null);
const stockTotal = d => (d.items || []).reduce((s, i) => s + (lineTotalOf(i) || 0), 0);

