// several vision models, to cross-check an invoice reading (returns [{model, content}], at most `max`)
async function llmChatMulti(models, messages, max) {
  const outs = []; let lastErr = null;
  for (const model of models) {
    if (outs.length >= max) break;
    try {
      const content = gemText(await gemCall(model, messages, false));
      if (!content.trim()) throw new Error('empty response from ' + model);
      outs.push({ model, content });
    } catch (e) { lastErr = e; }
  }
  if (!outs.length) throw lastErr || new Error('no vision model available');
  return outs;
}

// ---------- product catalog: the reference the bot checks every message against ----------
const UNIT_SYN = {
  carton: ['carton', 'كرتونة', 'كرتونه', 'كرتون', 'كارتونة', 'كراتين', 'كرتونات'],
  box: ['box', 'علبة', 'علبه', 'علب'],
  pack: ['pack', 'packet', 'باكو', 'باكت', 'باكوهات', 'عبوة', 'عبوه'],
  piece: ['piece', 'قطعة', 'قطعه', 'قطع', 'حبة', 'حبه'],
  dozen: ['dozen', 'دستة', 'دسته', 'دست'],
  bag: ['bag', 'كيس', 'اكياس', 'أكياس', 'شوال', 'شوالات'],
  bottle: ['bottle', 'زجاجة', 'زجاجه', 'ازازة', 'إزازة', 'قزازة'],
  kg: ['kg', 'كيلو', 'كجم']
};
const unitKey = u => {
  const n = normAr(u); if (!n) return '';
  for (const k of Object.keys(UNIT_SYN)) if (UNIT_SYN[k].some(a => normAr(a) === n)) return k;
  return n;
};
const sameUnit = (a, b) => !!a && !!b && unitKey(a) === unitKey(b);
const unitsOf = p => [p.unit].concat((p.alt_units || []).map(a => a.name)).filter(Boolean);
function unitFactor(p, unitText) {
  if (!unitText || sameUnit(unitText, p.unit)) return { factor: 1, known: true };
  for (const a of (p.alt_units || [])) if (sameUnit(unitText, a.name)) return { factor: Number(a.factor) > 0 ? Number(a.factor) : 1, known: true };
  return { factor: 1, known: false };
}
// code-side matching (does not depend on the AI): exact name/alias, or one clearly best fuzzy match
function matchProduct(text, products) {
  const n = normAr(text); if (!n) return null;
  const scored = products.map(p => ({ p, score: Math.max(...[p.name].concat(p.aliases || []).map(x => normAr(x) === n ? 1 : nameScore(text, x))) })).sort((a, b) => b.score - a.score);
  if (!scored.length || scored[0].score < 0.9) return null;
  if (scored[1] && scored[1].score >= 0.9 && scored[1].score >= scored[0].score - 0.05) return null;   // ambiguous
  return scored[0].p;
}
// normalizes items against the catalog (product, unit factor, base quantity) and returns warnings for the rep
function catalogCheck(items, products, mode) {
  const q = [];
  const byId = new Map(products.map(p => [p.id, p]));
  const tol = (Number(cfg.price_tolerance_pct) || 20) / 100;
  for (const it of items) {
    let p = it.product_id ? byId.get(it.product_id) : null;
    if (!p) p = matchProduct(it.product_text, products);
    it.factor = 1; it.base_qty = it.quantity; it.base_unit = it.unit || null;
    if (!p) {
      it.product_id = null;
      q.push('«' + it.product_text + '» مش في قايمة الأصناف (مش هيتخصم من العهدة ومفيش مرجع سعر).');
      continue;
    }
    it.product_id = p.id; it.product_text = p.name;
    if (!it.unit) it.unit = p.unit;
    const u = unitFactor(p, it.unit);
    if (!u.known) q.push('الوحدة «' + unitAr(it.unit) + '» مش معرّفة للصنف «' + p.name + '» (المعرّف: ' + unitsOf(p).map(unitAr).join('، ') + ').');
    it.factor = u.factor; it.base_qty = Math.round(it.quantity * u.factor * 100) / 100; it.base_unit = p.unit;
    if (it.unit_price != null && it.unit_price > 0) {
      const basePrice = it.unit_price / u.factor;
      const ref = mode === 'receipt' ? p.cost_price : p.default_price;
      const refName = mode === 'receipt' ? 'سعر المصنع' : 'سعر القايمة';
      const per = ' للـ' + unitAr(p.unit);
      if (mode === 'sale' && p.min_price != null && basePrice < Number(p.min_price) - 1e-9) {
        q.push('⚠️ سعر «' + p.name + '» (' + fmt(basePrice) + per + ') أقل من أقل سعر مسموح (' + fmt(p.min_price) + ').');
      } else if (ref != null && Number(ref) > 0) {
        const r = basePrice / Number(ref);
        if (r <= 0.2 || r >= 5) q.push('⚠️ سعر «' + p.name + '» (' + fmt(basePrice) + per + ') مختلف جدًا عن ' + refName + ' (' + fmt(ref) + ')، ممكن صفر غلط.');
        else if (Math.abs(r - 1) > tol) q.push('سعر «' + p.name + '» (' + fmt(basePrice) + per + ') غير ' + refName + ' (' + fmt(ref) + ').');
      }
    }
  }
  return q;
}
async function noteUnknownProducts(items, rep_id) {
  const names = Array.from(new Set((items || []).filter(i => !i.product_id && i.product_text).map(i => String(i.product_text).trim()).filter(Boolean)));
  for (const name of names) {
    try { await sb('POST', '/product_requests?on_conflict=tenant_id,name', { name, rep_id, last_seen: new Date().toISOString() }, 'resolution=merge-duplicates'); } catch (e) { /* table may not exist yet */ }
  }
}
const productsForPrompt = products => products.map(p => ({ id: p.id, name: p.name, aliases: p.aliases, units: unitsOf(p) }));

async function main() {
const inp = $input.first().json;
const { ctx, text, source } = inp;
const { rep, chat_id, visit_id, mode } = ctx;

const [products, clients, vrows] = await Promise.all([
  sb('GET', '/products?active=eq.true&select=id,name,aliases,unit,alt_units,default_price,min_price'),
  sb('GET', '/clients?select=id,name,aliases&order=created_at.desc&limit=1000' + (rep.is_manager ? '' : '&rep_id=eq.' + rep.id)),   // ISOLATION: a rep only ever sees (and gets matched against) his own clients
  sb('GET', '/visits?id=eq.' + visit_id + '&select=*')
]);
const visit = vrows[0];
if (!visit || visit.status !== 'draft') {
  await setSession(rep.id, { editing_visit_id: null });
  await send(chat_id, 'المسودة دي اتقفلت. ابعت زيارة جديدة.');
  return [];
}
const prev = (mode === 'correction' && visit.ai_json) ? Object.assign({}, visit.ai_json) : null;
if (prev) { delete prev._candidates; }

const now = nowInfo();
let sys = `You extract structured sales-visit data from a field sales rep's voice transcript or text.
The rep speaks Egyptian Arabic (or Gulf Arabic). The business: ${cfg.business || 'a distributor selling products to shops'}.

Return ONLY one valid JSON object. No markdown, no explanation.

RULES
1. Never invent data. If something is not stated, use null.
2. Convert spoken numbers to digits. Egyptian number words: مية=100, ميتين=200, تلتمية=300, ربعمية=400, خمسمية=500, ستمية=600, سبعمية=700, تمانمية=800, تسعمية=900, ألف=1000, ألفين=2000, تلات تلاف=3000, عشرة=10, عشرين=20, تلاتين=30, أربعين=40, خمسين=50, ستين=60, سبعين=70, تمانين=80, تسعين=90, "ونص"=+0.5. Combine them: "أربعمية وخمسين"=450, "ميتين وخمسين"=250, "ألف وخمسمية"=1500, "تمانمية"=800 (NEVER 1000). Convert Arabic-Indic digits to normal digits.
3. A price said with an item ("بـ 450") is the PRICE PER UNIT, unless the rep clearly says it is a total ("الإجمالي", "المجموع", "كله بـ"). If it is a total, divide by quantity and set "price_was_total": true on that item.
4. Match product names to the PRODUCTS list using names and aliases. If there is no confident match, set product_id to null and keep the rep's wording in product_text. If the rep names one of the product's units, use that unit word exactly; if he names another unit keep his word.
5. Match the client to the CLIENTS list. If more than one plausible match or none, set client_id to null and client_match to "low" or "none".
6. Relative dates ("بكرة", "الخميس", "بعد أسبوع") are resolved using NOW. Output ISO 8601 with the same timezone offset as NOW. If no time of day is stated, use 12:00. A weekday name means the NEXT occurrence of that day (never a past date).
7. visit_type: "sale" if items were sold; "collection" if the rep mainly collected money; otherwise "follow_up".
8. payment.status: "paid" (all paid), "partial" (some paid), "credit" (nothing paid, آجل), or "unknown" if not stated.
9. If the rep promises to collect money on a date ("هحصّل منه الخميس"), fill collection.due_at. Fill collection.amount_due ONLY if the rep says the amount to collect; otherwise leave it null (the system computes it).
10. Put anything the client said (objections, requests, competitor prices) in client_notes, short, in Arabic.
11. List in "questions" anything important that is unclear (max 3), phrased as short Arabic questions for the rep.
12. In CORRECTION MODE, when quantities, prices or payments change, set collection.amount_due to null unless the rep states a new amount.

INPUT CONTEXT
NOW: ${now.iso} (${now.day})
CURRENCY: ${cfg.currency}
PRODUCTS: ${JSON.stringify(productsForPrompt(products))}   // units = the units this product can be sold in
CLIENTS: ${JSON.stringify(clients.map(c => ({ id: c.id, name: c.name, aliases: c.aliases })))}

OUTPUT SCHEMA
{
  "client_id": string|null,
  "client_name": string|null,
  "client_match": "high"|"low"|"none",
  "visit_type": "sale"|"follow_up"|"collection",
  "items": [ { "product_id": string|null, "product_text": string, "quantity": number, "unit": string|null, "unit_price": number|null, "price_was_total": boolean } ],
  "payment": { "status": "paid"|"partial"|"credit"|"unknown", "amount_paid": number|null, "method": "cash"|"transfer"|"cheque"|null },
  "collection": { "due_at": string|null, "amount_due": number|null },
  "next_visit_at": string|null,
  "client_notes": string|null,
  "questions": [string]
}`;
if (prev) {
  sys += `

CORRECTION MODE
You are given the PREVIOUS_DRAFT (JSON) and a CORRECTION from the rep (voice transcript or text).
Apply ONLY the changes the rep asked for. Keep every other field exactly as in the draft.
If the correction is a complete new description of the visit, replace the draft entirely.
Return the full updated JSON in the same schema.

PREVIOUS_DRAFT: ${JSON.stringify(prev)}`;
}

// ---- call the LLM (falls back across cfg.llm_models) ----
let d = null, lastErr = null;
try {
  const r = await llmChat(cfg.llm_models, [{ role: 'system', content: sys }, { role: 'user', content: text }], true);
  d = parseJson(r.content);
} catch (e) { lastErr = e; }
if (!d) {
  if (mode === 'new') await sb('PATCH', '/visits?id=eq.' + visit_id, { status: 'cancelled' }).catch(() => {});
  await send(chat_id, '😕 حصلت مشكلة في فهم الرسالة. ابعتها تاني.' + (cfg.debug && lastErr ? '\n' + String(lastErr.message || lastErr).slice(0, 200) : ''));
  return [];
}

// ---- normalize ----
const pById = new Map(products.map(p => [p.id, p]));
d.items = (Array.isArray(d.items) ? d.items : []).filter(i => i && (i.product_text || i.product_id)).map(i => {
  const p = i.product_id ? pById.get(i.product_id) : null;
  const up = (i.unit_price !== null && i.unit_price !== undefined && !isNaN(Number(i.unit_price))) ? Number(i.unit_price) : null;
  return { product_id: p ? p.id : null, product_text: p ? p.name : (i.product_text || ''), quantity: Number(i.quantity) || 0, unit: i.unit || (p && p.unit) || null, unit_price: up, price_was_total: !!i.price_was_total };
});
d.visit_type = ['sale', 'follow_up', 'collection'].includes(d.visit_type) ? d.visit_type : (d.items.length ? 'sale' : 'follow_up');
d.payment = Object.assign({ status: 'unknown', amount_paid: null, method: null }, d.payment || {});
d.payment.amount_paid = (d.payment.amount_paid !== null && d.payment.amount_paid !== undefined && !isNaN(Number(d.payment.amount_paid))) ? Number(d.payment.amount_paid) : null;
if (!['cash', 'transfer', 'cheque'].includes(d.payment.method)) d.payment.method = null;
d.collection = Object.assign({ due_at: null, amount_due: null }, d.collection || {});
d.collection.due_at = validIso(d.collection.due_at);
d.collection.amount_due = (d.collection.amount_due !== null && d.collection.amount_due !== undefined && !isNaN(Number(d.collection.amount_due))) ? Number(d.collection.amount_due) : null;
d.next_visit_at = validIso(d.next_visit_at);
d.client_notes = d.client_notes || null;
d.questions = Array.isArray(d.questions) ? d.questions.filter(q => typeof q === 'string' && q).slice(0, 3) : [];

// ---- check every item against the product catalog (reference) ----
d.questions.push(...catalogCheck(d.items, products, 'sale'));
if (cfg.check_custody !== false && d.items.some(i => i.product_id)) {   // does he really hold what he says he sold?
  try {
    const held = await sb('GET', '/rep_stock?rep_id=eq.' + rep.id + '&select=product_id,on_hand');
    if (held.length) {   // only for reps who work with a custody (they registered factory invoices)
      const onHand = {}; held.forEach(h => { if (h.product_id) onHand[h.product_id] = Number(h.on_hand); });
      for (const it of d.items) {
        if (!it.product_id) continue;
        const oh = onHand[it.product_id] || 0;
        if (it.base_qty > oh + 1e-9) d.questions.push('معاك ' + fmt(oh) + ' ' + unitAr(it.base_unit) + ' بس من «' + it.product_text + '» والمباع ' + fmt(it.base_qty) + '.');
      }
    }
  } catch (e) { /* best effort */ }
}

// ---- client resolution ----
const cById = new Map(clients.map(c => [c.id, c]));
const known = d.client_id ? cById.get(d.client_id) : null;
delete d._candidates;
if (known) { d.client_id = known.id; d.client_name = known.name; d.client_match = 'high'; }
else {
  d.client_id = null;
  const cands = clientCandidates(d.client_name, clients);
  if (cands.length && cands[0].score >= 0.9 && (cands.length === 1 || cands[1].score < 0.7)) {
    d.client_id = cands[0].id; d.client_name = cands[0].name; d.client_match = 'high';
  } else if (prev && prev.client_match === 'new' && d.client_name && normAr(prev.client_name) === normAr(d.client_name)) {
    d.client_match = 'new';
  } else if (cands.length) {
    d.client_match = 'low'; d._candidates = cands.map(c => ({ id: c.id, name: c.name }));
  } else d.client_match = 'none';
}

// ---- money + sanity checks ----
const total = itemsTotal(d);
if (d.payment.status === 'paid' && d.payment.amount_paid === null && total > 0) d.payment.amount_paid = total;
if (d.payment.status === 'partial' && d.payment.amount_paid === null) d.questions.push('كام المبلغ اللي دفعه؟');
if (d.payment.amount_paid !== null && total > 0 && d.payment.amount_paid > total) d.questions.push('المبلغ المدفوع أكبر من الإجمالي، متأكد؟');
const prevAuto = !!(prev && prev.collection && prev.collection.auto === true);
if (prevAuto) d.collection.amount_due = null;   // the old amount was computed by us: recompute it after the correction
let amountAuto = false;
if (d.collection.due_at && d.collection.amount_due === null && d.payment.amount_paid !== null && total - d.payment.amount_paid > 0) { d.collection.amount_due = total - d.payment.amount_paid; amountAuto = true; }
if (d.collection.due_at && d.collection.amount_due === null && total > 0 && d.payment.status === 'credit') { d.collection.amount_due = total; amountAuto = true; }
d.collection.auto = amountAuto;
if (d.items.some(i => i.quantity <= 0 || i.quantity > 1000)) d.questions.push('في كمية غريبة، راجعها.');
if (d.collection.due_at && Date.parse(d.collection.due_at) < Date.now() - 3600000) d.questions.push('تاريخ التحصيل ده عدّى، تقصد تاريخ تاني؟');
if (d.next_visit_at && Date.parse(d.next_visit_at) < Date.now() - 3600000) d.questions.push('تاريخ الزيارة الجاية ده عدّى، تقصد تاريخ تاني؟');
d.questions = Array.from(new Set(d.questions)).slice(0, 6);
if (mode === 'correction') d._corrections = ((prev && prev._corrections) || []).concat([text]);

// ---- nothing useful in the message (noise, greeting...) -> do not keep a draft ----
const meaningful = d.items.length > 0 || (d.payment.amount_paid || 0) > 0 || d.collection.due_at || d.client_name || d.client_notes || d.next_visit_at;
if (mode === 'new' && !meaningful) {
  await sb('PATCH', '/visits?id=eq.' + visit_id, { status: 'cancelled', transcript: source === 'voice' ? text : null });
  await send(chat_id, '😕 ما فهمتش منها بيانات زيارة (عميل أو أصناف أو مبلغ). ابعت تفاصيل أوضح.');
