}

// ---- save draft ----
const patch = { ai_json: d, client_id: d.client_id, visit_type: d.visit_type, client_notes: d.client_notes, next_visit_at: d.next_visit_at };
if (source === 'voice' && mode === 'new') { patch.transcript = text; if (ctx.upload_ok === false) patch.voice_path = null; }
if (source === 'voice' && mode === 'correction' && ctx.upload_ok !== false && ctx.voice_path) patch.extra_voice_paths = (visit.extra_voice_paths || []).concat([ctx.voice_path]);
await sb('PATCH', '/visits?id=eq.' + visit_id, patch);
if (mode === 'correction') await setSession(rep.id, { editing_visit_id: null });

await send(chat_id, renderSummary(d, mode === 'correction' ? '✏️ بعد التعديل:' : '📋 ده اللي فهمته:'), { reply_markup: kb(visit_id, d) });
return [{ json: { ok: true, visit_id } }];

}
try { return await main(); }
catch (e) {
