// several vision models, to cross-check an invoice reading (returns [{model, content}], at most `max`)
async function llmChatMulti(models, messages, max) {
  const outs = []; let lastErr = null;
  for (const model of models) {
    if (outs.length >= max) break;
    try {
      const content = gemText(await gemCall(model, messages, false));
      if (!content.trim()) throw new Error('empty response from ' + model);
      outs.push({ model, content });
    } catch (e) { lastErr = e; }
  }
  if (!outs.length) throw lastErr || new Error('no vision model available');
  return outs;
}

// ---------- product catalog: the reference the bot checks every message against ----------
const UNIT_SYN = {
  carton: ['carton', 'كرتونة', 'كرتونه', 'كرتون', 'كارتونة', 'كراتين', 'كرتونات'],
  box: ['box', 'علبة', 'علبه', 'علب'],
  pack: ['pack', 'packet', 'باكو', 'باكت', 'باكوهات', 'عبوة', 'عبوه'],
  piece: ['piece', 'قطعة', 'قطعه', 'قطع', 'حبة', 'حبه'],
  dozen: ['dozen', 'دستة', 'دسته', 'دست'],
  bag: ['bag', 'كيس', 'اكياس', 'أكياس', 'شوال', 'شوالات'],
  bottle: ['bottle', 'زجاجة', 'زجاجه', 'ازازة', 'إزازة', 'قزازة'],
  kg: ['kg', 'كيلو', 'كجم']
};
const unitKey = u => {
  const n = normAr(u); if (!n) return '';
  for (const k of Object.keys(UNIT_SYN)) if (UNIT_SYN[k].some(a => normAr(a) === n)) return k;
  return n;
};
const sameUnit = (a, b) => !!a && !!b && unitKey(a) === unitKey(b);
const unitsOf = p => [p.unit].concat((p.alt_units || []).map(a => a.name)).filter(Boolean);
function unitFactor(p, unitText) {
  if (!unitText || sameUnit(unitText, p.unit)) return { factor: 1, known: true };
  for (const a of (p.alt_units || [])) if (sameUnit(unitText, a.name)) return { factor: Number(a.factor) > 0 ? Number(a.factor) : 1, known: true };
  return { factor: 1, known: false };
}
// code-side matching (does not depend on the AI): exact name/alias, or one clearly best fuzzy match
function matchProduct(text, products) {
  const n = normAr(text); if (!n) return null;
  const scored = products.map(p => ({ p, score: Math.max(...[p.name].concat(p.aliases || []).map(x => normAr(x) === n ? 1 : nameScore(text, x))) })).sort((a, b) => b.score - a.score);
  if (!scored.length || scored[0].score < 0.9) return null;
  if (scored[1] && scored[1].score >= 0.9 && scored[1].score >= scored[0].score - 0.05) return null;   // ambiguous
  return scored[0].p;
}
// normalizes items against the catalog (product, unit factor, base quantity) and returns warnings for the rep
function catalogCheck(items, products, mode) {
  const q = [];
  const byId = new Map(products.map(p => [p.id, p]));
  const tol = (Number(cfg.price_tolerance_pct) || 20) / 100;
  for (const it of items) {
    let p = it.product_id ? byId.get(it.product_id) : null;
    if (!p) p = matchProduct(it.product_text, products);
    it.factor = 1; it.base_qty = it.quantity; it.base_unit = it.unit || null;
    if (!p) {
      it.product_id = null;
      q.push('«' + it.product_text + '» مش في قايمة الأصناف (مش هيتخصم من العهدة ومفيش مرجع سعر).');
      continue;
    }
    it.product_id = p.id; it.product_text = p.name;
    if (!it.unit) it.unit = p.unit;
    const u = unitFactor(p, it.unit);
    if (!u.known) q.push('الوحدة «' + unitAr(it.unit) + '» مش معرّفة للصنف «' + p.name + '» (المعرّف: ' + unitsOf(p).map(unitAr).join('، ') + ').');
    it.factor = u.factor; it.base_qty = Math.round(it.quantity * u.factor * 100) / 100; it.base_unit = p.unit;
    if (it.unit_price != null && it.unit_price > 0) {
      const basePrice = it.unit_price / u.factor;
      const ref = mode === 'receipt' ? p.cost_price : p.default_price;
      const refName = mode === 'receipt' ? 'سعر المصنع' : 'سعر القايمة';
      const per = ' للـ' + unitAr(p.unit);
      if (mode === 'sale' && p.min_price != null && basePrice < Number(p.min_price) - 1e-9) {
        q.push('⚠️ سعر «' + p.name + '» (' + fmt(basePrice) + per + ') أقل من أقل سعر مسموح (' + fmt(p.min_price) + ').');
      } else if (ref != null && Number(ref) > 0) {
        const r = basePrice / Number(ref);
        if (r <= 0.2 || r >= 5) q.push('⚠️ سعر «' + p.name + '» (' + fmt(basePrice) + per + ') مختلف جدًا عن ' + refName + ' (' + fmt(ref) + ')، ممكن صفر غلط.');
        else if (Math.abs(r - 1) > tol) q.push('سعر «' + p.name + '» (' + fmt(basePrice) + per + ') غير ' + refName + ' (' + fmt(ref) + ').');
      }
    }
  }
  return q;
}
