  L.push('💼 قيمة العهدة: ' + fmt(tot));
  return L.join('\n');
}

// several vision models, to cross-check an invoice reading (returns [{model, content}], at most `max`)
async function llmChatMulti(models, messages, max) {
  const outs = []; let lastErr = null;
  for (const model of models) {
    if (outs.length >= max) break;
    try {
      const content = gemText(await gemCall(model, messages, false));
      if (!content.trim()) throw new Error('empty response from ' + model);
      outs.push({ model, content });
    } catch (e) { lastErr = e; }
  }
  if (!outs.length) throw lastErr || new Error('no vision model available');
  return outs;
}

// ---------- product catalog: the reference the bot checks every message against ----------
const UNIT_SYN = {
  carton: ['carton', 'كرتونة', 'كرتونه', 'كرتون', 'كارتونة', 'كراتين', 'كرتونات'],
  box: ['box', 'علبة', 'علبه', 'علب'],
  pack: ['pack', 'packet', 'باكو', 'باكت', 'باكوهات', 'عبوة', 'عبوه'],
  piece: ['piece', 'قطعة', 'قطعه', 'قطع', 'حبة', 'حبه'],
  dozen: ['dozen', 'دستة', 'دسته', 'دست'],
  bag: ['bag', 'كيس', 'اكياس', 'أكياس', 'شوال', 'شوالات'],
  bottle: ['bottle', 'زجاجة', 'زجاجه', 'ازازة', 'إزازة', 'قزازة'],
  kg: ['kg', 'كيلو', 'كجم']
};
const unitKey = u => {
  const n = normAr(u); if (!n) return '';
  for (const k of Object.keys(UNIT_SYN)) if (UNIT_SYN[k].some(a => normAr(a) === n)) return k;
  return n;
};
const sameUnit = (a, b) => !!a && !!b && unitKey(a) === unitKey(b);
const unitsOf = p => [p.unit].concat((p.alt_units || []).map(a => a.name)).filter(Boolean);
function unitFactor(p, unitText) {
  if (!unitText || sameUnit(unitText, p.unit)) return { factor: 1, known: true };
  for (const a of (p.alt_units || [])) if (sameUnit(unitText, a.name)) return { factor: Number(a.factor) > 0 ? Number(a.factor) : 1, known: true };
  return { factor: 1, known: false };
}
// code-side matching (does not depend on the AI): exact name/alias, or one clearly best fuzzy match
function matchProduct(text, products) {
  const n = normAr(text); if (!n) return null;
  const scored = products.map(p => ({ p, score: Math.max(...[p.name].concat(p.aliases || []).map(x => normAr(x) === n ? 1 : nameScore(text, x))) })).sort((a, b) => b.score - a.score);
  if (!scored.length || scored[0].score < 0.9) return null;
  if (scored[1] && scored[1].score >= 0.9 && scored[1].score >= scored[0].score - 0.05) return null;   // ambiguous
  return scored[0].p;
}
// normalizes items against the catalog (product, unit factor, base quantity) and returns warnings for the rep
function catalogCheck(items, products, mode) {
  const q = [];
  const byId = new Map(products.map(p => [p.id, p]));
  const tol = (Number(cfg.price_tolerance_pct) || 20) / 100;
  for (const it of items) {
    let p = it.product_id ? byId.get(it.product_id) : null;
    if (!p) p = matchProduct(it.product_text, products);
    it.factor = 1; it.base_qty = it.quantity; it.base_unit = it.unit || null;
    if (!p) {
      it.product_id = null;
      q.push('«' + it.product_text + '» مش في قايمة الأصناف (مش هيتخصم من العهدة ومفيش مرجع سعر).');
      continue;
    }
    it.product_id = p.id; it.product_text = p.name;
    if (!it.unit) it.unit = p.unit;
    const u = unitFactor(p, it.unit);
    if (!u.known) q.push('الوحدة «' + unitAr(it.unit) + '» مش معرّفة للصنف «' + p.name + '» (المعرّف: ' + unitsOf(p).map(unitAr).join('، ') + ').');
    it.factor = u.factor; it.base_qty = Math.round(it.quantity * u.factor * 100) / 100; it.base_unit = p.unit;
    if (it.unit_price != null && it.unit_price > 0) {
      const basePrice = it.unit_price / u.factor;
      const ref = mode === 'receipt' ? p.cost_price : p.default_price;
      const refName = mode === 'receipt' ? 'سعر المصنع' : 'سعر القايمة';
      const per = ' للـ' + unitAr(p.unit);
      if (mode === 'sale' && p.min_price != null && basePrice < Number(p.min_price) - 1e-9) {
        q.push('⚠️ سعر «' + p.name + '» (' + fmt(basePrice) + per + ') أقل من أقل سعر مسموح (' + fmt(p.min_price) + ').');
      } else if (ref != null && Number(ref) > 0) {
        const r = basePrice / Number(ref);
        if (r <= 0.2 || r >= 5) q.push('⚠️ سعر «' + p.name + '» (' + fmt(basePrice) + per + ') مختلف جدًا عن ' + refName + ' (' + fmt(ref) + ')، ممكن صفر غلط.');
        else if (Math.abs(r - 1) > tol) q.push('سعر «' + p.name + '» (' + fmt(basePrice) + per + ') غير ' + refName + ' (' + fmt(ref) + ').');
      }
    }
  }
  return q;
}
async function noteUnknownProducts(items, rep_id) {
  const names = Array.from(new Set((items || []).filter(i => !i.product_id && i.product_text).map(i => String(i.product_text).trim()).filter(Boolean)));
  for (const name of names) {
    try { await sb('POST', '/product_requests?on_conflict=tenant_id,name', { name, rep_id, last_seen: new Date().toISOString() }, 'resolution=merge-duplicates'); } catch (e) { /* table may not exist yet */ }
  }
}
const productsForPrompt = products => products.map(p => ({ id: p.id, name: p.name, aliases: p.aliases, units: unitsOf(p) }));

async function main() {
const nowMs = Date.now();
const iso = ms => new Date(ms).toISOString();
const enc = encodeURIComponent;
const GRACE = 30 * 60000;
const tz = cfg.timezone || 'Africa/Cairo';
const stats = { reminders_2h: 0, reminders_24h: 0, draft_reminders: 0, errors: 0 };

const fmtWhen = s => {
  const dt = new Date(s);
  const date = new Intl.DateTimeFormat('en-CA', { timeZone: tz }).format(dt);
  const time = new Intl.DateTimeFormat('en-GB', { timeZone: tz, hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(dt);
  return arDay(s) + ' ' + date + ' الساعة ' + time;
};
const sel = 'id,due_at,amount_due,client_id,reps(telegram_id,active,tenants(active)),clients(name,phone,lat,lng)';
const due = (flag, hours) => sb('GET', '/collections?status=eq.pending&' + flag + '=eq.false'
  + '&due_at=lte.' + enc(iso(nowMs + hours * 3600000)) + '&due_at=gt.' + enc(iso(nowMs - GRACE)) + '&select=' + sel);

function collectionMsg(c, kind, bal) {
  const cl = c.clients || {};
  const mins = Math.round((Date.parse(c.due_at) - nowMs) / 60000);
  const hrs = Math.round(mins / 60);
  const L = [kind === '2h' ? '⏰ تحصيل قريب' : '🔔 تذكير تحصيل', '👤 ' + (cl.name || '—')];
  L.push('🗓 ' + fmtWhen(c.due_at) + (kind === '2h' ? (mins > 5 ? ' (بعد حوالي ' + mins + ' دقيقة)' : ' (دلوقتي)') : ' (بعد حوالي ' + hrs + ' ساعة)'));
  if (c.amount_due) L.push('💵 المطلوب: ' + fmt(c.amount_due));
  if (bal > 0) L.push('💼 إجمالي مديونية العميل: ' + fmt(bal));
  if (cl.phone) L.push('📞 ' + cl.phone);
  if (cl.lat !== null && cl.lat !== undefined && cl.lng !== null && cl.lng !== undefined) L.push('📍 https://www.google.com/maps?q=' + cl.lat + ',' + cl.lng);
  L.push('\nبعد ما تحصّل، ابعت فويس بالمبلغ عشان يتسجل.');
  return L.join('\n');
}

// ---------- collection reminders ----------
const list2 = await due('reminded_2h', 2);
const list24 = await due('reminded_24h', 24);
const ids2 = new Set(list2.map(c => c.id));
const all = list2.map(c => ({ c, k: '2h' })).concat(list24.filter(c => !ids2.has(c.id)).map(c => ({ c, k: '24h' })));

let bal = {};
const cids = Array.from(new Set(all.map(x => x.c.client_id)));
if (cids.length) {
  try {
    const rows = await sb('GET', '/client_balances?client_id=in.(' + cids.join(',') + ')&select=client_id,balance');
    rows.forEach(r => { bal[r.client_id] = Number(r.balance); });
  } catch (e) { /* reminder still goes out without the balance line */ }
}
for (const { c, k } of all) {
  try {
    const rep = c.reps;
    if (!rep || !rep.telegram_id || rep.active === false || (rep.tenants && rep.tenants.active === false)) continue;
    await send(rep.telegram_id, collectionMsg(c, k, bal[c.client_id]));
    await sb('PATCH', '/collections?id=eq.' + c.id, k === '2h' ? { reminded_2h: true, reminded_24h: true } : { reminded_24h: true });
    if (k === '2h') stats.reminders_2h++; else stats.reminders_24h++;
  } catch (e) { stats.errors++; }
}

// ---------- unconfirmed drafts (older than 2h, newer than 48h) ----------
const hourNow = Number(new Intl.DateTimeFormat('en-GB', { timeZone: tz, hour: '2-digit', hourCycle: 'h23' }).format(new Date()));
const win = cfg.draft_reminder_window || [8, 22];
if (hourNow >= win[0] && hourNow < win[1]) {
  const drafts = await sb('GET', '/visits?status=eq.draft&draft_reminded=eq.false&ai_json=not.is.null'
    + '&created_at=lt.' + enc(iso(nowMs - 2 * 3600000)) + '&created_at=gt.' + enc(iso(nowMs - 48 * 3600000))
    + '&select=id,ai_json,reps(telegram_id,active,tenants(active))&limit=30');
  for (const v of drafts) {
    try {
      const rep = v.reps;
      if (!rep || !rep.telegram_id || rep.active === false || (rep.tenants && rep.tenants.active === false)) continue;
      await send(rep.telegram_id, renderSummary(v.ai_json, '⏰ زيارة لسه مستنية تأكيدك:'), { reply_markup: kb(v.id, v.ai_json) });
      await sb('PATCH', '/visits?id=eq.' + v.id, { draft_reminded: true });
      stats.draft_reminders++;
    } catch (e) { stats.errors++; }
  }

  const sdrafts = await sb('GET', '/stock_issues?status=eq.draft&draft_reminded=eq.false&ai_json=not.is.null'
    + '&created_at=lt.' + enc(iso(nowMs - 2 * 3600000)) + '&created_at=gt.' + enc(iso(nowMs - 48 * 3600000))
    + '&select=id,ai_json,reps(telegram_id,active,tenants(active))&limit=30');
  for (const v of sdrafts) {
    try {
      const rep = v.reps;
      if (!rep || !rep.telegram_id || rep.active === false || (rep.tenants && rep.tenants.active === false)) continue;
      await send(rep.telegram_id, renderStockSummary(v.ai_json, '⏰ فاتورة لسه مستنية تأكيدك:'), { reply_markup: kbStock(v.id, v.ai_json) });
      await sb('PATCH', '/stock_issues?id=eq.' + v.id, { draft_reminded: true });
      stats.draft_reminders++;
    } catch (e) { stats.errors++; }
  }
}
return [{ json: stats }];

}
try { return await main(); }
catch (e) {
  try { const c = $('Init').first().json.chat_id; if (c) await send(c, '⚠️ حصل خطأ، حاول تاني.' + (cfg.debug ? '\n' + String(e.message || e).slice(0, 300) : '')); } catch (_) {}
  throw e;
}
